/*
    MODULE: 05_dethi_luyentap.sql
    Mục đích: Đề thi thử, Bài tập luyện tập, Khảo sát đầu vào & Bộ câu hỏi theo Bài học
    Bao gồm:
     - 6 Bộ Khảo sát năng lực đầu vào A1 - C2 (20 câu/bộ đa dạng kỹ năng)
     - 21 Đề thi thử & Gói luyện tập (chuẩn hóa 100% số câu hỏi: THPT QG 50 câu, IELTS/TOEIC/VSTEP/Cambridge 30-40 câu, Quick Drills 10 câu)
     - Toàn bộ Snapshot liên kết câu hỏi vào đề thi trong CauHoiBaiTap
     - 36 Bộ câu hỏi ôn tập theo đúng 36 Bài học trong BoCauHoi & BoCauHoi_CauHoi
     - Xóa bỏ hoàn toàn bộ đề dummy AI củng cố
*/
USE TiengAnhAI;
GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO

EXEC sp_MSforeachtable 'ALTER TABLE ? NOCHECK CONSTRAINT ALL';
GO

-- 1. XÓA DỮ LIỆU ĐỀ THI & BÀI TẬP CŨ
IF OBJECT_ID('BoCauHoi_CauHoi', 'U') IS NOT NULL DELETE FROM BoCauHoi_CauHoi;
IF OBJECT_ID('BoCauHoi', 'U') IS NOT NULL DELETE FROM BoCauHoi;
IF OBJECT_ID('CauHoiBaiTap', 'U') IS NOT NULL DELETE FROM CauHoiBaiTap;
IF OBJECT_ID('BaiTapDeThi', 'U') IS NOT NULL DELETE FROM BaiTapDeThi WHERE MaBaiTapDeThi >= 0;
IF OBJECT_ID('CauTraLoiKhaoSat', 'U') IS NOT NULL DELETE FROM CauTraLoiKhaoSat;
IF OBJECT_ID('LuotKhaoSat', 'U') IS NOT NULL DELETE FROM LuotKhaoSat;
IF OBJECT_ID('CauHoiKhaoSat', 'U') IS NOT NULL DELETE FROM CauHoiKhaoSat;
IF OBJECT_ID('BaiKhaoSatDauVao', 'U') IS NOT NULL DELETE FROM BaiKhaoSatDauVao WHERE MaBaiKhaoSat >= 0;
IF OBJECT_ID('CauHoiDoAISinh', 'U') IS NOT NULL DELETE FROM CauHoiDoAISinh;
IF OBJECT_ID('YeuCauSinhDeAI', 'U') IS NOT NULL DELETE FROM YeuCauSinhDeAI;
IF OBJECT_ID('NoiDungHocTapAIBaiHoc', 'U') IS NOT NULL DELETE FROM NoiDungHocTapAIBaiHoc;

IF OBJECT_ID('BaiTapDeThi', 'U') IS NOT NULL DBCC CHECKIDENT ('BaiTapDeThi', RESEED, 0) WITH NO_INFOMSGS;
IF OBJECT_ID('BaiKhaoSatDauVao', 'U') IS NOT NULL DBCC CHECKIDENT ('BaiKhaoSatDauVao', RESEED, 0) WITH NO_INFOMSGS;
IF OBJECT_ID('BoCauHoi', 'U') IS NOT NULL DBCC CHECKIDENT ('BoCauHoi', RESEED, 0) WITH NO_INFOMSGS;
GO

-- 2. ĐỒNG BỘ TRÌNH ĐỘ CÂU HỎI THEO BÀI HỌC VÀ CAMBRIDGE STARTERS
UPDATE ch
SET ch.MaTrinhDo = bh.MaTrinhDo
FROM CauHoi ch
JOIN BaiHoc bh ON ch.MaBaiHoc = bh.MaBaiHoc
WHERE bh.MaTrinhDo IS NOT NULL;

UPDATE CauHoi
SET MaTrinhDo = 0
WHERE MaDinhDanhSeed BETWEEN 'SEED_EAI_031' AND 'SEED_EAI_060';
GO

-- 3. NẠP 6 BỘ KHẢO SÁT NĂNG LỰC ĐẦU VÀO A1 - C2 VÀ CÂU HỎI KHẢO SÁT
SET IDENTITY_INSERT BaiKhaoSatDauVao ON;
INSERT INTO BaiKhaoSatDauVao (MaBaiKhaoSat, TenBaiKhaoSat, MoTa, TongSoCauHoi, DangHoatDong, NgayTao)
VALUES 
    (1, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ A1 (Căn bản & Khởi động)', N'Bài kiểm tra chẩn đoán năng lực khởi động A1: Kiểm tra phản xạ từ vựng cơ bản, phát âm, giao tiếp chào hỏi và ngữ pháp thì hiện tại đơn.', 20, 1, SYSDATETIME()),
    (2, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ A2 (Sơ trung cấp Nền tảng)', N'Bài kiểm tra chẩn đoán năng lực A2: Đọc hiểu chỉ dẫn thường nhật, thì quá khứ đơn, so sánh tính từ và mẫu câu giao tiếp cơ sở.', 20, 1, SYSDATETIME()),
    (3, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ B1 (Trung cấp Độc lập)', N'Bài kiểm tra chẩn đoán năng lực B1: Sử dụng ngữ pháp hiện tại hoàn thành, câu điều kiện, cấu trúc viết email thương mại và đọc hiểu tổng hợp.', 20, 1, SYSDATETIME()),
    (4, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ B2 (Trung cao cấp Chuyên sâu)', N'Bài kiểm tra chẩn đoán năng lực B2: Phân tích mệnh đề quan hệ rút gọn, câu bị động đặc biệt, từ vựng học thuật và đọc hiểu báo chí thương mại.', 20, 1, SYSDATETIME()),
    (5, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ C1 (Cao cấp Học thuật)', N'Bài kiểm tra chẩn đoán năng lực C1: Cấu trúc đảo ngữ nâng cao, thành ngữ chuyên sâu, văn phong học thuật IELTS/VSTEP và đọc hiểu nghiên cứu chuyên ngành.', 20, 1, SYSDATETIME()),
    (6, N'Khảo sát Đánh giá Năng lực Đầu vào - Cấp độ C2 (Thành thạo Bản ngữ)', N'Bài kiểm tra chẩn đoán năng lực C2: Ngôn ngữ học thuật đỉnh cao, từ vựng trừu tượng, phân tích phản biện sắc bén và cấu trúc câu phức tạp.', 20, 1, SYSDATETIME()),
    (7, N'Khảo sát Đánh giá Năng lực Toàn diện - Tổng hợp Đa Cấp độ (A1 - C2)', N'Bài kiểm tra tổng hợp toàn diện phân tầng độ khó từ A1 đến C2: Đo lường chính xác năng lực thực tế hiện có của người học mà không cần chọn trước trình độ.', 20, 1, SYSDATETIME());
SET IDENTITY_INSERT BaiKhaoSatDauVao OFF;
GO

