-- 4. NẠP 21 ĐỀ THI THỬ & GÓI LUYỆN TẬP VÀO BaiTapDeThi
DECLARE @cdIELTS INT = 5, @cdGrammar INT = 9, @cdBusiness INT = 13, @cdDaily INT = 1, @gvId INT = 1;
