SELECT 3, 514, 21, 0.25, N'In Machine Learning, what is ''Overfitting''?', NULL, N'''Overfitting'' (Quá khớp) xảy ra khi mô hình học thuộc lòng quá kỹ dữ liệu huấn luyện (training data), dẫn đến khả năng tổng quát hóa kém trên dữ liệu mới (test data).', NULL, N'TracNghiem', N'TuVung', N'Kho', N'[{"MaLuaChon":1982,"KyHieuLuaChon":"A","NoiDungLuaChon":"When a computer program runs out of memory","LaDapAnDung":false},{"MaLuaChon":1983,"KyHieuLuaChon":"B","NoiDungLuaChon":"When a model learns training data noise too closely, resulting in poor generalization on unseen test data","LaDapAnDung":true},{"MaLuaChon":1984,"KyHieuLuaChon":"C","NoiDungLuaChon":"When a neural network has zero parameters","LaDapAnDung":false},{"MaLuaChon":1985,"KyHieuLuaChon":"D","NoiDungLuaChon":"When the training dataset is deleted accidentally","LaDapAnDung":false}]'
