SELECT 3, 519, 26, 0.25, N'What is ''Few-Shot Prompting'' in modern Large Language Model (LLM) interaction?', NULL, N'''Few-shot prompting'' là kỹ thuật cung cấp một vài cặp ví dụ mẫu (input - output examples) ngay trong câu nhắc để mô hình hiểu rõ định dạng và phong cách mong muốn trước khi xử lý yêu cầu chính.', NULL, N'TracNghiem', N'Doc', N'Kho', N'[{"MaLuaChon":2000,"KyHieuLuaChon":"A","NoiDungLuaChon":"Sending only short prompts under five words","LaDapAnDung":false},{"MaLuaChon":2001,"KyHieuLuaChon":"B","NoiDungLuaChon":"Providing a few explicit input-output demonstration examples within the prompt context before the target task","LaDapAnDung":true},{"MaLuaChon":2002,"KyHieuLuaChon":"C","NoiDungLuaChon":"Reloading the browser three times before prompting","LaDapAnDung":false},{"MaLuaChon":2003,"KyHieuLuaChon":"D","NoiDungLuaChon":"Training an entirely new neural network from scratch","LaDapAnDung":false}]'
