SELECT 8, 454, 1, 0.25, N'What is the primary operational distinction between ''Skimming'' and ''Scanning'' in IELTS Academic Reading?', NULL, N'''Skimming'' là kỹ thuật đọc lướt để nắm ý chính (gist) và bố cục toàn bài, còn ''Scanning'' là đọc quét mắt tìm từ khóa cụ thể (con số, tên riêng, thuật ngữ).', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":1769,"KyHieuLuaChon":"A","NoiDungLuaChon":"Skimming is for spelling checks, while scanning is for translation.","LaDapAnDung":false},{"MaLuaChon":1770,"KyHieuLuaChon":"B","NoiDungLuaChon":"Skimming quickly captures the central gist and paragraph structure, while scanning targets specific keywords, dates, and names.","LaDapAnDung":true},{"MaLuaChon":1771,"KyHieuLuaChon":"C","NoiDungLuaChon":"Scanning reads the entire passage slowly word-by-word.","LaDapAnDung":false},{"MaLuaChon":1772,"KyHieuLuaChon":"D","NoiDungLuaChon":"Both techniques require vocal reading out loud.","LaDapAnDung":false}]'
