SELECT 12, 48, 2, 1.00, N'What is a primary advantage of deep learning algorithms in radiology highlighted in the text?', N'The convergence of deep learning architectures and high-resolution imaging has transformed medical diagnostics. Computer vision algorithms can now analyze thousands of radiological scans within seconds, detecting micro-anomalies such as early-stage pulmonary nodules that human clinicians might overlook during fatigued night shifts. Despite these monumental achievements, computer scientists and medical ethicists stress that artificial intelligence should augment rather than supplant human physicians. Algorithmic outputs are inherently susceptible to training bias, and machines lack the nuanced bedside empathy essential for holistic patient care and complex palliative counseling.', N'Văn bản chỉ ra rằng thuật toán có thể phân tích hàng nghìn ảnh chụp trong vài giây và phát hiện những bất thường siêu nhỏ.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":192,"KyHieuLuaChon":"A","NoiDungLuaChon":"They perform surgeries without human assistance.","LaDapAnDung":false},{"MaLuaChon":193,"KyHieuLuaChon":"B","NoiDungLuaChon":"They rapidly scan massive image sets and detect microscopic anomalies.","LaDapAnDung":true},{"MaLuaChon":194,"KyHieuLuaChon":"C","NoiDungLuaChon":"They completely eliminate all diagnostic expenses.","LaDapAnDung":false},{"MaLuaChon":195,"KyHieuLuaChon":"D","NoiDungLuaChon":"They formulate medication formulas independently.","LaDapAnDung":false}]'
UNION ALL
