SELECT 22, 5, 27, 0.20, N'According to the passage, why do owls prefer hunting at night?', N'Owls are nocturnal birds of prey renowned for their extraordinary night vision and silent flight. Unlike daylight predators such as eagles and falcons, owls possess large, forward-facing eyes with a high concentration of rod cells that capture minimal ambient light. Furthermore, hunting under the cover of darkness significantly reduces competition for small rodents.', N'Đoạn văn nêu rõ: bóng tối giúp cú tránh sự cạnh tranh săn bắt các loài gặm nhấm từ các loài săn mồi ban ngày.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":20,"KyHieuLuaChon":"A","NoiDungLuaChon":"They cannot tolerate warm sunshine.","LaDapAnDung":false},{"MaLuaChon":21,"KyHieuLuaChon":"B","NoiDungLuaChon":"Their specialized senses excel in the dark and they avoid daytime competitors.","LaDapAnDung":true},{"MaLuaChon":22,"KyHieuLuaChon":"C","NoiDungLuaChon":"Rodents are only active during morning hours.","LaDapAnDung":false},{"MaLuaChon":23,"KyHieuLuaChon":"D","NoiDungLuaChon":"They prefer socializing in darkness.","LaDapAnDung":false}]'
UNION ALL
SELECT 22, 45, 28, 0.20, N'According to the passage, how does ecotourism differ primarily from conventional mass tourism?', N'Ecotourism has gained significant momentum in recent decades as travelers become more environmentally conscious. Unlike conventional mass tourism, which often strains local infrastructure and causes ecological degradation, ecotourism emphasizes environmental stewardship and cultural respect. Travelers visit pristine natural areas, support community-run conservation initiatives, and contribute directly to the local economy. However, experts caution that without stringent regulations, unchecked commercialization can turn sustainable destinations into overcrowded attractions, ultimately defeating the original conservation purpose.', N'Đoạn văn nêu rõ: du lịch sinh thái tập trung vào bảo vệ môi trường và tôn trọng văn hóa địa phương thay vì gây áp lực lên hạ tầng như du lịch đại chúng.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":180,"KyHieuLuaChon":"A","NoiDungLuaChon":"It prioritizes luxury accommodations over local experiences.","LaDapAnDung":false},{"MaLuaChon":181,"KyHieuLuaChon":"B","NoiDungLuaChon":"It focuses on environmental protection and cultural respect.","LaDapAnDung":true},{"MaLuaChon":182,"KyHieuLuaChon":"C","NoiDungLuaChon":"It strictly caters to international researchers.","LaDapAnDung":false},{"MaLuaChon":183,"KyHieuLuaChon":"D","NoiDungLuaChon":"It avoids using local economic resources.","LaDapAnDung":false}]'
UNION ALL
SELECT 22, 46, 29, 0.20, N'What potential hazard do conservation experts warn against regarding ecotourism?', N'Ecotourism has gained significant momentum in recent decades as travelers become more environmentally conscious. Unlike conventional mass tourism, which often strains local infrastructure and causes ecological degradation, ecotourism emphasizes environmental stewardship and cultural respect. Travelers visit pristine natural areas, support community-run conservation initiatives, and contribute directly to the local economy. However, experts caution that without stringent regulations, unchecked commercialization can turn sustainable destinations into overcrowded attractions, ultimately defeating the original conservation purpose.', N'Đoạn văn cảnh báo: nếu không có quy định nghiêm ngặt, thương mại hóa thiếu kiểm soát có thể khiến các điểm đến trở nên quá tải.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":184,"KyHieuLuaChon":"A","NoiDungLuaChon":"Overcrowding and commercialization without strict regulations.","LaDapAnDung":true},{"MaLuaChon":185,"KyHieuLuaChon":"B","NoiDungLuaChon":"A total loss of traditional farming techniques.","LaDapAnDung":false},{"MaLuaChon":186,"KyHieuLuaChon":"C","NoiDungLuaChon":"An immediate ban on international air transportation.","LaDapAnDung":false},{"MaLuaChon":187,"KyHieuLuaChon":"D","NoiDungLuaChon":"High expenditure on digital marketing campaigns.","LaDapAnDung":false}]'
