SELECT 22, 48, 31, 0.20, N'What is a primary advantage of deep learning algorithms in radiology highlighted in the text?', N'The convergence of deep learning architectures and high-resolution imaging has transformed medical diagnostics. Computer vision algorithms can now analyze thousands of radiological scans within seconds, detecting micro-anomalies such as early-stage pulmonary nodules that human clinicians might overlook during fatigued night shifts. Despite these monumental achievements, computer scientists and medical ethicists stress that artificial intelligence should augment rather than supplant human physicians. Algorithmic outputs are inherently susceptible to training bias, and machines lack the nuanced bedside empathy essential for holistic patient care and complex palliative counseling.', N'Văn bản chỉ ra rằng thuật toán có thể phân tích hàng nghìn ảnh chụp trong vài giây và phát hiện những bất thường siêu nhỏ.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":192,"KyHieuLuaChon":"A","NoiDungLuaChon":"They perform surgeries without human assistance.","LaDapAnDung":false},{"MaLuaChon":193,"KyHieuLuaChon":"B","NoiDungLuaChon":"They rapidly scan massive image sets and detect microscopic anomalies.","LaDapAnDung":true},{"MaLuaChon":194,"KyHieuLuaChon":"C","NoiDungLuaChon":"They completely eliminate all diagnostic expenses.","LaDapAnDung":false},{"MaLuaChon":195,"KyHieuLuaChon":"D","NoiDungLuaChon":"They formulate medication formulas independently.","LaDapAnDung":false}]'
UNION ALL
SELECT 22, 49, 32, 0.20, N'According to the passage, why should AI not entirely replace human doctors?', N'The convergence of deep learning architectures and high-resolution imaging has transformed medical diagnostics. Computer vision algorithms can now analyze thousands of radiological scans within seconds, detecting micro-anomalies such as early-stage pulmonary nodules that human clinicians might overlook during fatigued night shifts. Despite these monumental achievements, computer scientists and medical ethicists stress that artificial intelligence should augment rather than supplant human physicians. Algorithmic outputs are inherently susceptible to training bias, and machines lack the nuanced bedside empathy essential for holistic patient care and complex palliative counseling.', N'Đoạn văn nêu hai lý do: thuật toán có thể bị sai lệch dữ liệu huấn luyện (training bias) và máy móc thiếu sự thấu cảm trong chăm sóc bệnh nhân.', NULL, N'TracNghiem', N'Doc', N'TrungBinh', N'[{"MaLuaChon":196,"KyHieuLuaChon":"A","NoiDungLuaChon":"Algorithms are prone to training bias and lack emotional empathy.","LaDapAnDung":true},{"MaLuaChon":197,"KyHieuLuaChon":"B","NoiDungLuaChon":"Deep learning models consume excessive hospital electricity.","LaDapAnDung":false},{"MaLuaChon":198,"KyHieuLuaChon":"C","NoiDungLuaChon":"Medical equipment is incompatible with digital computing systems.","LaDapAnDung":false},{"MaLuaChon":199,"KyHieuLuaChon":"D","NoiDungLuaChon":"Doctors refuse to interact with software interfaces.","LaDapAnDung":false}]'
UNION ALL
