-- 6. NẠP CÁC BỘ CÂU HỎI THEO BÀI HỌC VÀO BoCauHoi & BoCauHoi_CauHoi
DECLARE @gvId INT = 1;
SET IDENTITY_INSERT BoCauHoi ON;

INSERT INTO BoCauHoi (MaBoCauHoi, TenBoCauHoi, MoTa, NguonTao, TenNguon, MaBaiHoc, MaChuDe, MaTrinhDo, NguoiTao, LoaiBoCauHoi, TrangThai, NgayTao)
SELECT 
    bh.MaBaiHoc + 1,
    N'Bộ câu hỏi ôn tập: ' + bh.TieuDe,
    N'Bộ câu hỏi trắc nghiệm & củng cố kiến thức trích xuất trực tiếp từ bài giảng ' + bh.TieuDe,
    N'GiaoVien',
    N'Tổ chuyên môn EAI',
    bh.MaBaiHoc,
    bh.MaChuDe,
    bh.MaTrinhDo,
    @gvId,
    N'OnTapBaiHoc',
    N'HoanThanh',
    SYSDATETIME()
FROM BaiHoc bh;

SET IDENTITY_INSERT BoCauHoi OFF;
GO

INSERT INTO BoCauHoi_CauHoi (MaBoCauHoi, MaCauHoi, ThuTu)
SELECT 
    b.MaBoCauHoi,
    c.MaCauHoi,
    ROW_NUMBER() OVER (PARTITION BY b.MaBoCauHoi ORDER BY c.MaCauHoi ASC) AS ThuTu
FROM BoCauHoi b
INNER JOIN CauHoi c ON b.MaBaiHoc = c.MaBaiHoc;
GO

EXEC sp_MSforeachtable 'ALTER TABLE ? WITH CHECK CHECK CONSTRAINT ALL';
GO

